function taskMatches(f,t){if(t.deleted)return false;const q=el.search.value.trim().toLowerCase();const text=[f.zh,f.en,f.desc,...f.examples,t.name,t.scene,t.items,t.primaryObject,t.description,t.prompt].join(" ").toLowerCase();return(el.scene.value==="all"||t.scene===el.scene.value)&&(!q||text.includes(q));}
function visibleFamilies(){const filtering=el.scene.value!=="all"||Boolean(el.search.value.trim());return TASK_FAMILIES.map(f=>({...f,matched:f.tasks.filter(t=>taskMatches(f,t))})).filter(f=>!filtering||f.matched.length);}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function splitTaskItems(items){const parts=String(items).split(/[、，,]/).map(v=>v.trim()).filter(Boolean);return{primary:parts[0]||"目标物体",parts}}
function primaryObject(task){return task.primaryObject||splitTaskItems(task.items).primary}
function fixedReferences(task){if(task.fixedObjects)return task.fixedObjects;const {parts}=splitTaskItems(task.items),primary=primaryObject(task);let removed=false;const references=parts.filter(part=>{if(!removed&&(part.includes(primary)||primary.includes(part))){removed=true;return false}return true});if(!removed)references.shift();return references.join("、")||"无固定参照物"}
function instanceObject(task,variant){const primary=primaryObject(task);return variant.en?`${variant.zh}${primary}`:primary}
function instanceOptions(task,instances=null){const list=instances?.length?instances:INSTANCE_VARIANTS.map(variant=>({id:variant.id,name:instanceObject(task,variant)}));return list.map((instance,index)=>`<option value="${index}">${escapeHtml(instance.name||"未命名实例")}</option>`).join("")}
function taskOverridesStorageKey(){return"unitree-task-overrides"}
function normalizedTaskMaterials(item,fallback=""){const source=Array.isArray(item?.materialNames)?item.materialNames:[item?.primaryObject||fallback];return[...new Set(source.map(value=>String(value||"").trim()).filter(Boolean))]}
function normalizeTaskOverrides(value){if(!value||typeof value!=="object"||Array.isArray(value))return{};return Object.fromEntries(Object.entries(value).filter(([id,item])=>/^F\d{2}-(?:T\d{2,}|C\d{3})$/.test(id)&&item&&typeof item==="object").map(([id,item])=>{if(item.deleted)return[id,{deleted:true}];const materialNames=normalizedTaskMaterials(item);return[id,{name:String(item.name||"").trim(),description:String(item.description||"").trim(),prompt:String(item.prompt||"").trim(),...(materialNames.length?{primaryObject:materialNames[0],materialNames}:{}),...(item.custom?{custom:true,family:Number(item.family||id.slice(1,3)),scene:String(item.scene||"").trim()}: {})}]}))}
async function readTaskOverrides(){try{const response=await supabaseRequest("shared_records?kind=eq.task&select=record_key,value,updated_at");if(response.ok){const rows=await response.json(),tasks=normalizeTaskOverrides(Object.fromEntries(rows.map(row=>[row.record_key,row.value])));try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(tasks))}catch{}return tasks}}catch{}try{return normalizeTaskOverrides(JSON.parse(localStorage.getItem(taskOverridesStorageKey())||"{}"))}catch{return{}}}
function syncCustomTasks(overrides){TASK_FAMILIES.forEach(f=>{f.tasks=f.tasks.filter(task=>!task.custom);f.tasks.forEach(task=>{task.storageId=task.storageId||task.id;const saved=overrides[task.storageId]||{};task.deleted=Boolean(saved.deleted);const materials=normalizedTaskMaterials(saved,task.primaryObject||splitTaskItems(task.items).primary);task.materialNames=materials;task.primaryObject=materials[0]||task.primaryObject})});Object.entries(overrides).filter(([,task])=>task.custom).sort(([a],[b])=>a.localeCompare(b)).forEach(([storageId,task])=>{const family=TASK_FAMILIES.find(f=>f.n===task.family),materials=normalizedTaskMaterials(task);if(family&&task.scene&&materials.length)family.tasks.push({id:storageId,storageId,custom:true,name:task.name,description:task.description,prompt:task.prompt,scene:task.scene,items:materials.join("、"),primaryObject:materials[0],materialNames:materials})});TASK_FAMILIES.forEach(f=>{let index=0;f.tasks.forEach(task=>{if(!task.deleted)task.id=`F${String(f.n).padStart(2,"0")}-T${String(++index).padStart(2,"0")}`})})}
