async function createCustomTask(family,task){try{const prefix=`F${String(family).padStart(2,"0")}-T`,numbers=Object.keys(sharedTaskOverrides).filter(id=>id.startsWith(prefix)).map(id=>Number(id.slice(prefix.length))).filter(Number.isFinite),baseCount=TASK_FAMILIES.find(f=>f.n===family)?.tasks.filter(item=>!item.custom).length||10,id=`${prefix}${String(Math.max(baseCount,...numbers,0)+1).padStart(2,"0")}`,value={...task,custom:true,family};const response=await supabaseRequest("shared_records?on_conflict=kind,record_key",{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify({kind:"task",record_key:id,value})});if(response.status===401||response.status===403){editorPassword="";try{sessionStorage.removeItem("unitree-material-editor-password")}catch{}return{status:"unauthorized"}}if(!response.ok)return{status:"error"};sharedTaskOverrides[id]=value;try{localStorage.setItem(taskOverridesStorageKey(),JSON.stringify(sharedTaskOverrides))}catch{}syncCustomTasks(sharedTaskOverrides);return{status:"ok",id}}catch{return{status:"offline"}}}
